import {finishEvolution} from './evolution-planner-client.mjs?v=finish1';
import {currentUser,supabase,loadSettings,accountUrl} from './auth-client.mjs';
import {loadRoster} from './my-tatari-client.mjs';
import {rosterTier} from './my-tatari-model.mjs?v=level-cap2400';
import {loadAppData} from './site-data.mjs?v=site-data5';
import {MAX_GOALS,planGoal,validateGoals,trialKey,eventWindows} from './evolution-planner-model.mjs?v=finish1';
const $=id=>document.getElementById(id),el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n},root=new URL('./tatari-data/',import.meta.url);
const image=(path,alt)=>{const n=el('img');n.src=new URL(path,root);n.alt=alt;n.loading='lazy';return n};
let catalog,schedule,roster,levels=null,actor=null,generation=0,goals=[],progress={},wishboxes=0,plans=[],finishing=false,finishSelection=null;
const key=()=> 'evolution-plan-preview-v1:'+actor;
function store(){if(!actor)return;try{localStorage.setItem(key(),JSON.stringify({goals,progress,wishboxes}))}catch{}}
function eligible(){return catalog.units.filter(u=>roster.units[u.id]?.owned&&u.forms.some(f=>f.evolution>roster.units[u.id].tier)&&!goals.some(g=>g.unit===u.id))}
function drawPicker(){const q=$('goal-search').value.trim().toLowerCase(),options=eligible().filter(u=>u.forms.some(f=>f.name.en.toLowerCase().includes(q)));$('goal-options').replaceChildren(...options.map(u=>{const owned=roster.units[u.id],form=u.forms.find(f=>f.evolution===owned.tier),b=el('button');b.type='button';b.setAttribute('aria-label','Plan '+form.name.en);b.append(image(form.portrait,form.name.en),el('strong',form.name.en),el('small','Tier '+rosterTier(u,owned.tier)+' · '+owned.stars+' stars'));b.onclick=()=>{if(goals.length>=MAX_GOALS)return;goals.push({unit:u.id,target:u.forms.find(f=>f.evolution>owned.tier).evolution});$('goal-picker').close();store();render()};return b}));$('picker-empty').hidden=options.length>0}
function art(unit,form){const n=el('div',undefined,'evo-art');n.append(image('images/tier-'+rosterTier(unit,form.evolution)+'.png',''),image(form.portrait,form.name.en));n.lastChild.className='evo-unit';return n}
function requirement(q,p,step){const row=el('div',undefined,'evo-requirement'+(q.done?' done':'')),copy=el('div');if(q.icons?.[0]){const icon=el('img');icon.src=q.icons[0];icon.alt='';row.append(icon)}else row.append(el('span',q.done?'✓':'○'));copy.append(el('p',q.text.en));if(q.automatic)copy.append(el('small','From saved settings · '+q.current+' / '+q.target));else if(!q.done)copy.append(el('small',q.missing.toLocaleString('en')+' remaining · enter progress shown in game'));row.append(copy);
 if(q.automatic)row.append(el('span',q.done?'✓ Met':q.missing+' missing',q.done?'evo-done':'evo-progress'));
 else{const label=el('label',undefined,'evo-progress'),input=el('input'),id=trialKey(p.unit.id,step.form.evolution,q.sourceQuestId),numeric=q.condition.includes('Counter(')&&!q.condition.includes(' and ')&&!q.condition.includes(' or ');if(numeric){input.type='number';input.min=0;input.max=q.target;input.step='any';input.value=q.current;input.setAttribute('aria-label',p.target.name.en+' trial '+q.sourceQuestId+' progress');label.append(input,el('span','/ '+q.target.toLocaleString('en')));input.onchange=()=>{const value=Number(input.value);progress[id]=Number.isFinite(value)?Math.max(0,Math.min(q.target,value)):0;store();render()}}else{input.type='checkbox';input.checked=q.done;input.setAttribute('aria-label','Completed: '+q.text.en);input.onchange=()=>{progress[id]=input.checked?q.target:0;store();render()};label.append(input,el('span','Completed'))}row.append(label)}return row}
function goalCard(p){const article=el('article',undefined,'evo-goal'),top=el('div',undefined,'evo-goal-top'),pair=el('div',undefined,'evo-art-pair'),title=el('div',undefined,'evo-goal-title'),remove=el('button','×','evo-remove');pair.append(art(p.unit,p.current),el('span','›'),art(p.unit,p.target));title.append(el('h3',p.current.name.en),el('p','Currently Tier '+rosterTier(p.unit,p.current.evolution)+' · '+p.owned.stars+' stars'));const target=el('select');target.setAttribute('aria-label','Evolution goal for '+p.current.name.en);for(const f of p.unit.forms.filter(f=>f.evolution>p.owned.tier))target.append(new Option('Goal: '+f.name.en+' · Tier '+rosterTier(p.unit,f.evolution),f.evolution));target.value=p.target.evolution;target.onchange=()=>{goals.find(g=>g.unit===p.unit.id).target=Number(target.value);store();render()};title.append(target,el('span',p.ready?'Ready to attempt':p.missingStars?'Needs '+p.missingStars+' more '+(p.missingStars===1?'star':'stars'):'Check remaining trials','evo-state'+(p.ready?' ready':'')));remove.type='button';remove.setAttribute('aria-label','Remove '+p.current.name.en+' goal');remove.onclick=()=>{goals=goals.filter(g=>g.unit!==p.unit.id);store();render()};top.append(pair,title,remove);const facts=el('div',undefined,'evo-goal-facts');facts.append(el('span','Stars '+p.owned.stars+' / '+p.requiredStars),el('span',p.copies+' copies missing'),el('strong',p.wishboxEligible?p.wishboxes+' Wishboxes':'Wishboxes not eligible'));
 const detail=el('details'),summary=el('summary');summary.textContent='Requirements · '+p.requirements.filter(q=>q.done).length+' / '+p.requirements.length+' checked · '+p.steps.length+' evolution '+(p.steps.length===1?'step':'steps');detail.append(summary);for(const step of p.steps){const block=el('section',undefined,'evo-step');block.append(el('h4',step.form.name.en+' → '+step.next.name.en),el('div',step.requiredStars===null?'Star requirement unavailable':step.requiredStars+' stars required'+(p.owned.stars>=step.requiredStars?' · ✓ Met':''),'evo-step-star'));if(!step.quests.length)block.append(el('p','No additional trial tasks recorded.'));for(const q of step.quests)block.append(requirement(q,p,step));detail.append(block)}const actions=el('div',undefined,'evo-goal-actions'),finish=el('button','Finish evolution','btn secondary');finish.type='button';finish.setAttribute('aria-label','Finish evolution to '+p.target.name.en);finish.onclick=()=>openFinish(p);actions.append(finish);article.dataset.unit=p.unit.id;article.append(top,facts,detail,actions);return article}
function openFinish(p){if(finishing||!actor)return;finishSelection={unit:p.unit.id,target:p.target.evolution,actor,token:generation};$('finish-title').textContent='Finish evolution to '+p.target.name.en+'?';$('finish-art').replaceChildren(art(p.unit,p.current),el('span','→'),art(p.unit,p.target));$('finish-summary').textContent='Confirm you have completed this evolution in game. Save Tier '+rosterTier(p.unit,p.target.evolution)+' to My Tatari and remove this goal.';$('finish-error').textContent='';$('finish-save').textContent='Save to My Tatari';$('finish-evolution').showModal()}
function finishBusy(value){finishing=value;for(const control of document.querySelectorAll('#evo-content button,#evo-content select,#evo-content input,#finish-evolution button'))control.disabled=value;}
$('finish-cancel').onclick=()=>{if(!finishing)$('finish-evolution').close()};$('finish-evolution').addEventListener('cancel',e=>{if(finishing)e.preventDefault()});
$('finish-form').onsubmit=async e=>{e.preventDefault();if(finishing||!finishSelection)return;const selected={...finishSelection};if(selected.actor!==actor||selected.token!==generation)return;finishBusy(true);$('finish-save').textContent='Saving…';$('finish-error').textContent='';try{const result=await finishEvolution(catalog,selected.actor,{unit:selected.unit,target:selected.target});if(selected.token!==generation||selected.actor!==actor)return;roster=result.roster;goals=goals.filter(g=>{if(g.unit===selected.unit)return false;try{planGoal(catalog,roster,g);return true}catch{return false}});for(const id of Object.keys(progress))if(id.startsWith(selected.unit+':'))delete progress[id];store();$('finish-evolution').close();finishSelection=null;render();const unit=catalog.units.find(u=>u.id===selected.unit),form=unit.forms.find(f=>f.evolution===roster.units[selected.unit].tier);$('evo-status').textContent=form.name.en+(result.saved?' saved to My Tatari. Goal completed.':' is already saved in My Tatari. Goal completed.');}catch(error){if(selected.token===generation)$('finish-error').textContent=error.message+' Your goal has been kept.';}finally{if(selected.token===generation){finishBusy(false);$('finish-save').textContent='Save to My Tatari';if(roster)render()}}};
const formatDate=ms=>new Intl.DateTimeFormat('en',{day:'numeric',month:'short',timeZone:'UTC'}).format(ms);
function opportunityHeads(ids){const row=el('div',undefined,'evo-window-heads');for(const id of ids){const target=plans.find(p=>p.unit.id===id).target,head=image(target.playerhead,target.name.en);head.title=target.name.en;row.append(head)}return row}
function render(){if(!roster||!actor)return;plans=goals.map(g=>planGoal(catalog,roster,g,progress,levels));$('goal-count').textContent=goals.length+' / '+MAX_GOALS;$('add-goal').disabled=goals.length>=MAX_GOALS||!eligible().length;$('goal-empty').hidden=goals.length>0;$('suggest-goals').disabled=!eligible().length;const open=new Set([...document.querySelectorAll('.evo-goal:has(details[open])')].map(n=>n.dataset.unit));$('goal-list').replaceChildren(...plans.map(goalCard));for(const row of document.querySelectorAll('.evo-goal'))if(open.has(row.dataset.unit))row.querySelector('details').open=true;const total=plans.reduce((sum,p)=>sum+p.wishboxes,0);$('wishbox-total').textContent=total.toLocaleString('en');$('wishbox-shortfall').textContent=Math.max(0,total-wishboxes).toLocaleString('en');$('wishbox-owned').value=wishboxes;const unsupported=plans.filter(p=>!p.wishboxEligible&&p.copies).reduce((sum,p)=>sum+p.copies,0);$('wishbox-note').textContent='One Wishbox supplies one eligible Tatari copy. Saved star progress is deducted.'+(unsupported?' '+unsupported+' starter Tatari copies must come from other sources.':'')+' Support Tatari upgrades and other trial requirements are not included.';const windows=eventWindows(plans,schedule);$('event-list').replaceChildren(...windows.map(w=>{const box=el('article',undefined,'evo-window');box.append(el('h3',w.name),el('p',w.name==='Horde Invasion'?(w.live?'Live now · until ':'Starts ')+new Intl.DateTimeFormat('en',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23',timeZone:'UTC'}).format(w.live?w.end:w.start)+' UTC':w.live?'Live now · through '+formatDate(w.end-1):formatDate(w.start)+' – '+formatDate(w.end-1),w.live?'evo-live':''),opportunityHeads(w.units));return box}));if(!windows.length)$('event-list').append(el('p',plans.length?'No matching event windows in the current schedule.':'Choose a goal to see relevant event windows.'));const link=el('a','View full schedule');link.href=new URL('./schedule.html',import.meta.url);$('event-list').append(link);$('evo-source').textContent='Trial and copy data: v0.49.1. Wishbox budget covers star copies for these goals; missing support Tatari and other resources are listed in requirements.'}
async function loadActor(){const token=++generation;actor=null;roster=null;finishSelection=null;finishBusy(false);$('finish-evolution').close();goals=[];progress={};wishboxes=0;levels=null;$('goal-picker').close();$('evo-content').hidden=true;$('evo-status').textContent='Loading your Tatari…';try{const user=await currentUser();if(token!==generation)return;if(!user){$('evo-status').replaceChildren(el('span','Log in to plan with your saved Tatari. '));const a=el('a','My Account');a.href=accountUrl;$('evo-status').append(a);return}const [row,badges]=await Promise.all([loadRoster(user.id),loadSettings().catch(()=>null)]);if(token!==generation)return;actor=user.id;roster=row?.roster||{accountLevel:1,units:{}};levels=badges;try{const saved=JSON.parse(localStorage.getItem(key())||'null');if(saved){goals=validateGoals(saved.goals).filter(g=>{try{planGoal(catalog,roster,g);return true}catch{return false}});progress=saved.progress&&typeof saved.progress==='object'?saved.progress:{};wishboxes=Math.max(0,Math.min(999999,Number(saved.wishboxes)||0))}}catch{}store();$('evo-status').textContent='';$('evo-content').hidden=false;render()}catch(e){if(token===generation)$('evo-status').textContent='Could not load your roster. '+e.message}}
$('add-goal').onclick=()=>{if(!actor||goals.length>=MAX_GOALS)return;$('goal-search').value='';drawPicker();$('goal-picker').showModal();$('goal-search').focus()};$('close-picker').onclick=()=>$('goal-picker').close();$('goal-search').oninput=drawPicker;$('suggest-goals').onclick=()=>{const options=eligible().map(u=>{const tier=roster.units[u.id].tier;return {unit:u.id,target:u.forms.find(f=>f.evolution>tier).evolution}}).sort((a,b)=>{const pa=planGoal(catalog,roster,a),pb=planGoal(catalog,roster,b);return Number(pb.requirements.some(q=>q.events.length))-Number(pa.requirements.some(q=>q.events.length))||pa.copies-pb.copies});goals.push(...options.slice(0,Math.min(3,MAX_GOALS-goals.length)));store();render()};$('wishbox-owned').onchange=()=>{const value=Number($('wishbox-owned').value);wishboxes=Number.isFinite(value)?Math.max(0,Math.min(999999,Math.floor(value))):0;store();render()};
try{const [units,costs,events]=await Promise.all([fetch(new URL('roster.json',root)).then(r=>{if(!r.ok)throw Error('Tatari data unavailable.');return r.json()}),fetch(new URL('star-progression.json',root)).then(r=>{if(!r.ok)throw Error('Star costs unavailable.');return r.json()}),loadAppData()]);catalog=units;catalog.starProgression=costs;schedule=events;await loadActor();supabase.auth.onAuthStateChange(event=>{if(event!=='TOKEN_REFRESHED')setTimeout(loadActor,0)})}catch(e){$('evo-status').textContent=e.message}
